fn frombuffer(buffer: &Vec<u8>, count: usize, offset: usize) -> Vec<u8> {
    // Safety of this slice is guaranteed by the problem assumptions:
    // 1. offset + count <= buffer.len()
    // 2. If count > 0 then offset < buffer.len()
    buffer[offset..offset + count].to_vec()
}

